(* [comment removed for export] *)
Lemma call_srcread (fx : FPState) R M model s sm cr (p k X : Z) :
  getr R (reg 1) = Z_to_bv 64 X -> L5.ra_ok X -> getr R (reg 2) = Z_to_bv 64 (S - 64) -> kept7 R ->
  getr R (reg 10) = Z_to_bv 64 (fb + 72) -> getr R (reg 11) = Z_to_bv 64 p -> getr R (reg 12) = Z_to_bv 64 k ->
  1 <= k <= PM.CHUNK -> tbdst s p k -> state_ok M model s sm cr ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (src' : PM.srcst) (sm' : PM.strm) (d : Z),
     regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 d -> 0 <= d <= k ->
     PMSP.consumed (PM.p_src s) src' sm sm' = d -> (d < k -> PM.unread src' sm' = 0) ->                 (* [comment removed for export] *)
     (d = 0 -> PM.sm_st sm' = 2) -> PMSP.src_step (PM.p_src s) src' sm sm' ->
     L5.bytes_at RSEGS M' p (UbjRef.slice pl (PEC.pos_of pl (PM.p_src s) sm) d) ->                    (* [comment removed for export] *)
     (forall l, PM.vs_data (fb + 384) (PM.p_tb s) + Z.of_nat (length l) <= p -> Z.of_nat (length l) <= PM.vs_size (PM.p_tb s) ->   (* [comment removed for export] *)
        L5.bytes_at RSEGS M (PM.vs_data (fb + 384) (PM.p_tb s)) l -> L5.bytes_at RSEGS M' (PM.vs_data (fb + 384) (PM.p_tb s)) l) ->
     state_ok M' model (PMPS.with_src s src') sm' cr ->
     srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' X M' model) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x39138 M model) K.
