(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma call_filltb (fx : FPState) R M model s sm cr (p X c0 n0 q0 : Z) :
  getr R (reg 1) = Z_to_bv 64 X -> L5.ra_ok X -> getr R (reg 2) = Z_to_bv 64 (S - 64) -> kept7 R ->
  getr R (reg 10) = Z_to_bv 64 (fb + 72) -> getr R (reg 11) = Z_to_bv 64 p -> getr R (reg 12) = Z_to_bv 64 PM.CHUNK ->
  PM.p_tb s = PM.VLong c0 n0 q0 -> q0 <= p -> p + PM.CHUNK <= q0 + c0 -> state_ok M model s sm cr -> PM.sr_rem (PM.p_src s) = 0 ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (sm' : PM.strm) (c : Z),
     regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 c -> 0 <= c <= PM.CHUNK -> PM.sm_g sm' = PM.sm_g sm + c ->
     (c < PM.CHUNK -> PM.sm_g sm' = PM.sm_eg sm /\ PM.sm_st sm' = 2) -> (PM.sm_st sm = 2 -> c = 0) ->
     PMSP.src_step (PM.p_src s) (PM.p_src s) sm sm' ->
     L5.bytes_at RSEGS M' p (UbjRef.slice pl (blen pl - (PM.sm_eg sm - PM.sm_g sm)) c) ->                 (* [comment removed for export] *)
     (forall l, PM.vs_data (fb + 384) (PM.p_tb s) + Z.of_nat (length l) <= p -> Z.of_nat (length l) <= PM.vs_size (PM.p_tb s) ->   (* [comment removed for export] *)
        L5.bytes_at RSEGS M (PM.vs_data (fb + 384) (PM.p_tb s)) l -> L5.bytes_at RSEGS M' (PM.vs_data (fb + 384) (PM.p_tb s)) l) ->
     state_ok M' model s sm' cr ->
     srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' X M' model) K) ->
